interface Declaration { readonly value: number; }
interface SourceFile { readonly endFlowNode: number; }
const absent = ABSENT;
const declarations: Declaration[] = [{ value: 7 }];
function getSourceFileOfNode(node: Declaration): SourceFile | undefined { return absent ? undefined : { endFlowNode: node.value }; }
const file = getSourceFileOfNode(declarations[0]);
const value: SourceFile = file;
console.log(value === undefined ? "undefined" : `${value.endFlowNode}`);
